from __future__ import annotations

from .models import Error


class LumenAPIError(Exception):
    """Base class for all API-level errors.

    Carries the HTTP ``status_code`` and, when the server returned a
    structured error body, the parsed :class:`~lumen.models.Error`.
    """

    def __init__(self, message: str, *, status_code: int, error: Error | None = None) -> None:
        super().__init__(message)
        self.status_code = status_code
        self.error = error

    def __repr__(self) -> str:
        return (
            f"{type(self).__name__}(status_code={self.status_code}, "
            f"error={self.error!r}, message={str(self)!r})"
        )


class NotFoundError(LumenAPIError):
    """The requested resource does not exist (HTTP 404)."""


class RateLimitError(LumenAPIError):
    """Rate limit exceeded and retries were exhausted (HTTP 429)."""

    def __init__(
        self,
        message: str,
        *,
        status_code: int = 429,
        error: Error | None = None,
        retry_after: float | None = None,
    ) -> None:
        super().__init__(message, status_code=status_code, error=error)
        self.retry_after = retry_after


class ConflictError(LumenAPIError):
    """The request conflicts with current resource state (HTTP 409)."""


class StaleCursorError(LumenAPIError):
    """A pagination cursor has expired (HTTP 410)."""
