import random

import pytest

from lumen import LumenClient
from lumen.testing import MockLumenServer


class RecordingSleep:
    """Stand-in for time.sleep that records requested durations."""

    def __init__(self) -> None:
        self.calls: list[float] = []

    def __call__(self, seconds: float) -> None:
        self.calls.append(seconds)


class ZeroJitter(random.Random):
    """RNG whose uniform() always returns the lower bound (no jitter)."""

    def uniform(self, a: float, b: float) -> float:
        return a


class FixedJitter(random.Random):
    """RNG whose uniform() always returns a fixed value."""

    def __init__(self, value: float) -> None:
        super().__init__(0)
        self.value = value

    def uniform(self, a: float, b: float) -> float:
        return self.value


